    category: 'Professional Development',
    tags: ['networking', 'relationship building', 'professional development', 'mentorship'],
    featuredImage: '/images/blog/networking-relationship-building-young-entrepreneurs.jpg',
    seoKeywords: ['networking young entrepreneurs', 'relationship building kids', 'youth professional networking', 'entrepreneurship networking skills'],
    metaDescription: 'Learn essential networking and relationship building skills for young entrepreneurs. Discover strategies to build meaningful professional connections and support networks.'
